begin;
create table public.fornecedores (
 id uuid primary key,oficina_id uuid not null references public.oficinas(id),nome text not null check(length(trim(nome)) between 2 and 160),documento text not null default '' check(length(documento)<=20),telefone text not null default '' check(telefone='' or telefone~'^\+[1-9][0-9]{7,14}$'),email text not null default '' check(length(email)<=254),endereco text not null default '' check(length(endereco)<=500),observacoes text not null default '' check(length(observacoes)<=2000),revisao integer not null default 1,arquivado_em timestamptz,criado_em timestamptz not null default now(),unique(oficina_id,id));
create unique index fornecedor_documento_unico on public.fornecedores(oficina_id,documento) where documento<>'' and arquivado_em is null;
create table public.compras_estoque (
 id uuid primary key,oficina_id uuid not null references public.oficinas(id),fornecedor_id uuid not null,nome_fornecedor text not null,documento text not null default '' check(length(documento)<=100),data date not null,observacoes text not null default '' check(length(observacoes)<=2000),total_centavos bigint not null check(total_centavos between 1 and 10000000000),cancelado_em timestamptz,motivo_cancelamento text,criado_por uuid not null references auth.users(id),criado_em timestamptz not null default now(),unique(oficina_id,id),foreign key(oficina_id,fornecedor_id) references public.fornecedores(oficina_id,id));
create unique index compra_documento_unico on public.compras_estoque(oficina_id,fornecedor_id,documento) where documento<>'' and cancelado_em is null;
create table public.itens_compra_estoque (
 id uuid primary key default gen_random_uuid(),oficina_id uuid not null,compra_id uuid not null,produto_id uuid not null,descricao text not null,quantidade numeric(15,3) not null check(quantidade>0),custo_centavos bigint not null check(custo_centavos>=0),total_centavos bigint not null,saldo_anterior numeric(15,3) not null,custo_anterior bigint not null,revisao_apos integer not null,
 foreign key(oficina_id,compra_id) references public.compras_estoque(oficina_id,id),foreign key(oficina_id,produto_id) references public.estoque_produtos(oficina_id,item_catalogo_id),unique(compra_id,produto_id));
alter table public.titulos_financeiros add column compra_id uuid,add column provisorio boolean not null default false,add column pagamento_combinado boolean not null default false,add foreign key(oficina_id,compra_id) references public.compras_estoque(oficina_id,id);
create unique index compra_titulo_unico on public.titulos_financeiros(oficina_id,compra_id) where compra_id is not null;
alter table public.movimentacoes_estoque add column compra_id uuid,add foreign key(oficina_id,compra_id) references public.compras_estoque(oficina_id,id);
alter table public.fornecedores enable row level security;alter table public.compras_estoque enable row level security;alter table public.itens_compra_estoque enable row level security;
grant select on public.fornecedores,public.compras_estoque,public.itens_compra_estoque to authenticated;
create policy fornecedores_leitura on public.fornecedores for select to authenticated using(private.is_workshop_member(oficina_id) and private.has_feature(oficina_id,'inventory'));
create policy compras_leitura on public.compras_estoque for select to authenticated using(private.has_feature(oficina_id,'inventory') and private.has_feature(oficina_id,'finance') and exists(select 1 from public.membros_oficina where oficina_id=compras_estoque.oficina_id and usuario_id=auth.uid() and ativo and perfil in ('owner','manager')));
create policy itens_compra_leitura on public.itens_compra_estoque for select to authenticated using(exists(select 1 from public.compras_estoque c where c.oficina_id=itens_compra_estoque.oficina_id and c.id=itens_compra_estoque.compra_id));
create index compras_periodo on public.compras_estoque(oficina_id,data desc,id);
create function public.listar_fornecedores(p_oficina uuid,p_busca text default '',p_arquivados boolean default false,p_pagina integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$declare itens jsonb;total bigint;begin
 perform private.exigir_estoque(p_oficina);select count(*) into total from public.fornecedores where oficina_id=p_oficina and (arquivado_em is not null)=p_arquivados and concat(nome,' ',documento) ilike '%'||left(p_busca,100)||'%';
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into itens from (select * from public.fornecedores where oficina_id=p_oficina and (arquivado_em is not null)=p_arquivados and concat(nome,' ',documento) ilike '%'||left(p_busca,100)||'%' order by nome,id limit 30 offset greatest(p_pagina,0)*30)x;return jsonb_build_object('itens',itens,'total',total);end $$;
create function public.salvar_fornecedor(p_oficina uuid,p_id uuid,p_dados jsonb,p_revisao integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare f public.fornecedores%rowtype;u uuid;begin
 u:=private.exigir_estoque(p_oficina);if p_id is null then raise exception 'Identificador obrigatório' using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended(p_oficina::text||p_id::text,0));
 select * into f from public.fornecedores where oficina_id=p_oficina and id=p_id for update;if found and p_revisao is null then return p_id;end if;
 if f.id is not null and (f.revisao is distinct from p_revisao or f.arquivado_em is not null) then raise exception 'Fornecedor alterado ou arquivado. Atualize a tela.' using errcode='40001';end if;
 insert into public.fornecedores(id,oficina_id,nome,documento,telefone,email,endereco,observacoes) values(p_id,p_oficina,trim(p_dados->>'nome'),regexp_replace(coalesce(p_dados->>'documento',''),'[^0-9]','','g'),coalesce(p_dados->>'telefone',''),coalesce(p_dados->>'email',''),coalesce(p_dados->>'endereco',''),coalesce(p_dados->>'observacoes','')) on conflict(id) do update set nome=excluded.nome,documento=excluded.documento,telefone=excluded.telefone,email=excluded.email,endereco=excluded.endereco,observacoes=excluded.observacoes,revisao=fornecedores.revisao+1 where fornecedores.oficina_id=p_oficina;
 insert into public.registros_auditoria(oficina_id,usuario_autor_id,tipo_autor,acao,tipo_entidade,entidade_id,correlacao_id) values(p_oficina,u,'user','Fornecedor cadastrado ou atualizado','fornecedor',p_id,gen_random_uuid());return p_id;end $$;
create function public.arquivar_fornecedor(p_oficina uuid,p_id uuid,p_revisao integer,p_arquivar boolean) returns void language plpgsql security definer set search_path='' as $$begin
 perform private.exigir_estoque(p_oficina);if p_arquivar is null then raise exception 'Ação obrigatória' using errcode='22023';end if;update public.fornecedores set arquivado_em=case when p_arquivar then now() else null end,revisao=revisao+1 where oficina_id=p_oficina and id=p_id and revisao=p_revisao;if not found then raise exception 'Fornecedor alterado. Atualize a tela.' using errcode='40001';end if;end $$;
create function public.registrar_compra_estoque(p_oficina uuid,p_id uuid,p_fornecedor uuid,p_data date,p_vencimento date,p_documento text,p_observacoes text,p_itens jsonb,p_pago bigint default 0,p_conta text default 'banco',p_forma text default 'pix') returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid;f public.fornecedores%rowtype;i record;e public.estoque_produtos%rowtype;total bigint;titulo uuid;novo_custo bigint;begin
 u:=private.exigir_financeiro(p_oficina);perform private.exigir_estoque(p_oficina);
 if p_id is null or p_data is null or p_data>(now() at time zone 'America/Sao_Paulo')::date or p_vencimento is null or jsonb_typeof(p_itens) is distinct from 'array' or jsonb_array_length(p_itens) not between 1 and 100 then raise exception 'Confira data, vencimento e itens da compra.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_oficina::text||p_id::text,0));if exists(select 1 from public.compras_estoque where oficina_id=p_oficina and id=p_id) then return p_id;end if;
 select * into f from public.fornecedores where oficina_id=p_oficina and id=p_fornecedor and arquivado_em is null for share;if not found then raise exception 'Selecione um fornecedor ativo desta oficina.' using errcode='22023';end if;
 if exists(select 1 from jsonb_to_recordset(p_itens) as j(produto_id uuid,quantidade numeric,custo_centavos bigint) where produto_id is null or quantidade is null or quantidade not between 0.001 and 1000000 or quantidade<>round(quantidade,3) or custo_centavos is null or custo_centavos not between 0 and 100000000) or (select count(distinct x->>'produto_id') from jsonb_array_elements(p_itens)x)<>jsonb_array_length(p_itens) then raise exception 'Confira produtos, quantidades e custos. Não repita o mesmo produto.' using errcode='22023';end if;
 select sum(round(quantidade*custo_centavos)) into total from jsonb_to_recordset(p_itens) as j(quantidade numeric,custo_centavos bigint);
 if total not between 1 and 10000000000 or p_pago is null or p_pago<0 or p_pago>total then raise exception 'Confira o total e o valor pago.' using errcode='22023';end if;
 perform 1 from public.estoque_produtos where oficina_id=p_oficina and item_catalogo_id in(select (x->>'produto_id')::uuid from jsonb_array_elements(p_itens)x) order by item_catalogo_id for update;
 insert into public.compras_estoque(id,oficina_id,fornecedor_id,nome_fornecedor,documento,data,observacoes,total_centavos,criado_por) values(p_id,p_oficina,f.id,f.nome,trim(coalesce(p_documento,'')),p_data,coalesce(p_observacoes,''),total,u);
 for i in select * from jsonb_to_recordset(p_itens) as j(produto_id uuid,quantidade numeric,custo_centavos bigint) order by produto_id loop
 select * into e from public.estoque_produtos where oficina_id=p_oficina and item_catalogo_id=i.produto_id;
 if not found or not exists(select 1 from public.itens_catalogo where oficina_id=p_oficina and id=i.produto_id and arquivado_em is null) then raise exception 'Uma peça está arquivada ou não tem controle de estoque.' using errcode='22023';end if;
 novo_custo:=round((e.saldo*e.custo_centavos+i.quantidade*i.custo_centavos)/(e.saldo+i.quantidade));
 update public.estoque_produtos set saldo=saldo+i.quantidade,custo_centavos=novo_custo,revisao=revisao+1 where oficina_id=p_oficina and item_catalogo_id=i.produto_id;
 insert into public.itens_compra_estoque(oficina_id,compra_id,produto_id,descricao,quantidade,custo_centavos,total_centavos,saldo_anterior,custo_anterior,revisao_apos) select p_oficina,p_id,i.produto_id,c.descricao,i.quantidade,i.custo_centavos,round(i.quantidade*i.custo_centavos),e.saldo,e.custo_centavos,e.revisao+1 from public.itens_catalogo c where c.oficina_id=p_oficina and c.id=i.produto_id;
 insert into public.movimentacoes_estoque(oficina_id,item_catalogo_id,tipo,quantidade,saldo_apos,custo_centavos,motivo,documento,chave,criado_por,compra_id) values(p_oficina,i.produto_id,'entrada',i.quantidade,e.saldo+i.quantidade,i.custo_centavos,'Compra de '||left(f.nome,160),p_documento,gen_random_uuid(),u,p_id);
 end loop;
 insert into public.titulos_financeiros(oficina_id,natureza,descricao,categoria,valor_centavos,competencia,vencimento,pessoa,observacoes,compra_id,criado_por) values(p_oficina,'pagar','Compra · '||left(f.nome,160),'compra_estoque',total,p_data,p_vencimento,f.nome,coalesce(p_observacoes,''),p_id,u) returning id into titulo;
 if p_pago>0 then perform public.baixar_titulo_financeiro(p_oficina,titulo,gen_random_uuid(),p_pago,0,p_data,p_conta,p_forma,'Pagamento informado na compra');end if;
 perform private.evento_financeiro(p_oficina,titulo,'Compra registrada e estoque recebido');return p_id;end $$;
create function public.listar_compras_estoque(p_oficina uuid,p_busca text default '',p_pagina integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$declare itens jsonb;total bigint;begin
 perform private.exigir_financeiro(p_oficina);perform private.exigir_estoque(p_oficina);
 select count(*) into total from public.compras_estoque where oficina_id=p_oficina and concat(nome_fornecedor,' ',documento) ilike '%'||left(p_busca,100)||'%';
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into itens from(select c.*,t.id titulo_id,t.baixado_centavos,t.aberto_centavos,t.vencimento from public.compras_estoque c join private.financeiro_saldos t on t.compra_id=c.id and t.oficina_id=c.oficina_id where c.oficina_id=p_oficina and concat(c.nome_fornecedor,' ',c.documento) ilike '%'||left(p_busca,100)||'%' order by c.data desc,c.criado_em desc,c.id limit 30 offset greatest(p_pagina,0)*30)x;return jsonb_build_object('itens',itens,'total',total);end $$;
create function public.consultar_compra_estoque(p_oficina uuid,p_compra uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 perform private.exigir_financeiro(p_oficina);perform private.exigir_estoque(p_oficina);
 select to_jsonb(c)||jsonb_build_object('titulo',to_jsonb(t),'itens',(select jsonb_agg(to_jsonb(i)) from public.itens_compra_estoque i where i.oficina_id=p_oficina and i.compra_id=c.id)) into r from public.compras_estoque c join private.financeiro_saldos t on t.compra_id=c.id and t.oficina_id=c.oficina_id where c.oficina_id=p_oficina and c.id=p_compra;
 if r is null then raise exception 'Compra não encontrada' using errcode='P0002';end if;return r;end $$;
create function public.cancelar_compra_estoque(p_oficina uuid,p_compra uuid,p_motivo text) returns void language plpgsql security definer set search_path='' as $$declare c public.compras_estoque%rowtype;i record;u uuid;t uuid;begin
 u:=private.exigir_financeiro(p_oficina);perform private.exigir_estoque(p_oficina);select * into c from public.compras_estoque where oficina_id=p_oficina and id=p_compra for update;if not found then raise exception 'Compra não encontrada' using errcode='P0002';end if;if c.cancelado_em is not null then return;end if;
 if length(trim(coalesce(p_motivo,''))) not between 3 and 1000 then raise exception 'Informe o motivo do cancelamento.' using errcode='22023';end if;
 select id into t from public.titulos_financeiros where oficina_id=p_oficina and compra_id=p_compra for update;
 if (select baixado_centavos from private.financeiro_saldos where id=t)<>0 then raise exception 'Estorne os pagamentos desta compra no financeiro antes de cancelar.' using errcode='22023';end if;
 perform 1 from public.estoque_produtos where oficina_id=p_oficina and item_catalogo_id in(select produto_id from public.itens_compra_estoque where compra_id=p_compra) order by item_catalogo_id for update;
 for i in select ic.*,e.revisao,m.id movimento from public.itens_compra_estoque ic join public.estoque_produtos e on e.oficina_id=ic.oficina_id and e.item_catalogo_id=ic.produto_id join public.movimentacoes_estoque m on m.oficina_id=ic.oficina_id and m.compra_id=ic.compra_id and m.item_catalogo_id=ic.produto_id and m.tipo='entrada' where ic.oficina_id=p_oficina and ic.compra_id=p_compra loop
 if i.revisao<>i.revisao_apos then raise exception 'Há alterações posteriores em uma peça. Esta compra não pode mais ser cancelada automaticamente.' using errcode='22023';end if;
 update public.estoque_produtos set saldo=i.saldo_anterior,custo_centavos=i.custo_anterior,revisao=revisao+1 where oficina_id=p_oficina and item_catalogo_id=i.produto_id;
 insert into public.movimentacoes_estoque(oficina_id,item_catalogo_id,tipo,quantidade,saldo_apos,custo_centavos,motivo,estorno_de,chave,criado_por,compra_id) values(p_oficina,i.produto_id,'estorno',-i.quantidade,i.saldo_anterior,i.custo_centavos,p_motivo,i.movimento,gen_random_uuid(),u,p_compra);
 end loop;
 update public.titulos_financeiros set cancelado_em=now(),motivo_cancelamento=p_motivo,revisao=revisao+1 where id=t;
 update public.compras_estoque set cancelado_em=now(),motivo_cancelamento=p_motivo where id=p_compra;
 perform private.evento_financeiro(p_oficina,t,'Compra cancelada com reversão do estoque');end $$;

create function public.preparar_financeiro_os(p_oficina uuid,p_os uuid) returns uuid language plpgsql security definer set search_path='' as $$declare w public.ordens_servico%rowtype;t uuid;u uuid;begin
 u:=private.exigir_financeiro(p_oficina);perform private.exigir_os(p_oficina);select * into w from public.ordens_servico where oficina_id=p_oficina and id=p_os for update;
 if not found or w.situacao='cancelled' or w.total_centavos<=0 then raise exception 'Inclua os itens da OS antes de registrar o pagamento. OS cancelada não pode receber.' using errcode='22023';end if;
 select id into t from public.titulos_financeiros where oficina_id=p_oficina and ordem_servico_id=p_os and automatico and cancelado_em is null;if found then return t;end if;
 insert into public.titulos_financeiros(oficina_id,natureza,descricao,categoria,valor_centavos,competencia,vencimento,pessoa,ordem_servico_id,automatico,provisorio,criado_por) values(p_oficina,'receber','OS #'||w.numero,'servicos',w.total_centavos,coalesce((w.entregue_em at time zone 'America/Sao_Paulo')::date,(now() at time zone 'America/Sao_Paulo')::date),(now() at time zone 'America/Sao_Paulo')::date,coalesce(w.dados_cliente->>'nome','Cliente'),w.id,true,w.situacao<>'delivered',u)
 on conflict(oficina_id,ordem_servico_id) where automatico do update set cancelado_em=null,motivo_cancelamento=null,valor_centavos=excluded.valor_centavos,provisorio=excluded.provisorio,revisao=titulos_financeiros.revisao+1 returning id into t;return t;end $$;
create function public.consultar_financeiro_os(p_oficina uuid,p_os uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 perform private.exigir_financeiro(p_oficina);perform private.exigir_os(p_oficina);if not exists(select 1 from public.ordens_servico where oficina_id=p_oficina and id=p_os) then raise exception 'OS não encontrada' using errcode='P0002';end if;
 select to_jsonb(t) into r from private.financeiro_saldos t where oficina_id=p_oficina and ordem_servico_id=p_os and automatico and cancelado_em is null;return r;end $$;
create function public.combinar_pagamento_os(p_oficina uuid,p_os uuid,p_vencimento date) returns void language plpgsql security definer set search_path='' as $$declare t uuid;begin
 if p_vencimento is null then raise exception 'Informe o vencimento combinado.' using errcode='22023';end if;t:=public.preparar_financeiro_os(p_oficina,p_os);update public.titulos_financeiros set vencimento=p_vencimento,pagamento_combinado=true,revisao=revisao+1 where id=t;perform private.evento_financeiro(p_oficina,t,'Data de pagamento combinada na OS');end $$;
create or replace function private.gerar_financeiro_os() returns trigger language plpgsql security definer set search_path='' as $$declare t public.titulos_financeiros%rowtype;pago bigint;begin
 if new.situacao=old.situacao and new.total_centavos=old.total_centavos then return new;end if;
 select * into t from public.titulos_financeiros where oficina_id=new.oficina_id and ordem_servico_id=new.id and automatico for update;
 if found then
 select baixado_centavos into pago from private.financeiro_saldos where id=t.id;
 if pago>new.total_centavos or (new.situacao='cancelled' and pago>0) then raise exception 'A OS possui pagamentos. Estorne o valor recebido antes de cancelar ou reduzir abaixo do que já foi pago.' using errcode='22023';end if;
 update public.titulos_financeiros set valor_centavos=greatest(new.total_centavos,1),provisorio=new.situacao<>'delivered',competencia=case when new.situacao='delivered' then (new.entregue_em at time zone 'America/Sao_Paulo')::date else competencia end,cancelado_em=case when new.situacao='cancelled' or new.total_centavos=0 then now() else null end,motivo_cancelamento=case when new.situacao='cancelled' or new.total_centavos=0 then 'OS cancelada ou sem valor' else null end,revisao=revisao+1 where id=t.id;
 elsif new.situacao='delivered' and old.situacao<>'delivered' and new.total_centavos>0 then
 insert into public.titulos_financeiros(oficina_id,natureza,descricao,categoria,valor_centavos,competencia,vencimento,pessoa,ordem_servico_id,automatico,criado_por) values(new.oficina_id,'receber','OS #'||new.numero,'servicos',new.total_centavos,(new.entregue_em at time zone 'America/Sao_Paulo')::date,(new.entregue_em at time zone 'America/Sao_Paulo')::date,coalesce(new.dados_cliente->>'nome','Cliente'),new.id,true,auth.uid());end if;
 if new.situacao='delivered' and old.situacao<>'delivered' and new.total_centavos>0 then perform private.evento_financeiro(new.oficina_id,new.id,'os_generated');end if;return new;end $$;
drop trigger os_financeiro on public.ordens_servico;
create trigger os_financeiro after update of situacao,subtotal_centavos,desconto_centavos on public.ordens_servico for each row execute function private.gerar_financeiro_os();

create or replace view private.financeiro_saldos as select t.id,t.oficina_id,t.natureza,t.descricao,t.categoria,t.valor_centavos,t.competencia,t.vencimento,t.pessoa,t.observacoes,t.transferencia_id,t.ordem_servico_id,t.automatico,t.custos_revisados,t.cancelado_em,t.motivo_cancelamento,t.revisao,t.criado_por,t.criado_em,coalesce(b.baixado,0)::bigint as baixado_centavos,(t.valor_centavos-coalesce(b.baixado,0))::bigint as aberto_centavos,t.compra_id,t.provisorio,t.pagamento_combinado from public.titulos_financeiros t left join lateral(select sum(case when estorno_de is null then valor_centavos else -valor_centavos end) baixado from public.baixas_financeiras where titulo_id=t.id and oficina_id=t.oficina_id) b on true;
create or replace function public.consultar_financeiro(p_oficina uuid,p_inicio date,p_fim date,p_busca text default '',p_filtro text default 'abertos',p_natureza text default '',p_pagina integer default 0,p_os uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare resumo jsonb;lista jsonb;total bigint;contas jsonb;os jsonb;begin
 perform private.exigir_financeiro(p_oficina);
 if p_inicio is null or p_fim is null or p_inicio>p_fim or p_fim-p_inicio>366 then raise exception 'Selecione um período de até 367 dias.' using errcode='22023';end if;
 with t as(select * from private.financeiro_saldos where oficina_id=p_oficina and cancelado_em is null),
 b as(select x.*,t.natureza,t.categoria,case when x.estorno_de is null then 1 else -1 end sinal from public.baixas_financeiras x join public.titulos_financeiros t on t.id=x.titulo_id where x.oficina_id=p_oficina and x.data between p_inicio and p_fim),
 c as(select coalesce(sum(round(-m.quantidade*m.custo_centavos)),0) valor from public.movimentacoes_estoque m where m.oficina_id=p_oficina and m.ordem_servico_id is not null and (m.criado_em at time zone 'America/Sao_Paulo')::date between p_inicio and p_fim)
 select jsonb_build_object(
 'receitas',coalesce((select sum(valor_centavos) from t where not provisorio and natureza='receber' and categoria in ('servicos','outras_receitas') and competencia between p_inicio and p_fim),0),
 'despesas',coalesce((select sum(valor_centavos) from t where natureza='pagar' and categoria not in ('compra_estoque','retirada','saldo_inicial','transferencia') and competencia between p_inicio and p_fim),0),
 'pecas',(select valor from c),'taxas',coalesce((select sum(sinal*taxa_centavos) from b),0),
 'entradas',coalesce((select sum(sinal*(valor_centavos-taxa_centavos)) from b where natureza='receber' and categoria<>'transferencia'),0),
 'saidas',coalesce((select sum(sinal*valor_centavos) from b where natureza='pagar' and categoria<>'transferencia'),0),
 'receber',coalesce((select sum(aberto_centavos) from t where natureza='receber'),0),
 'pagar',coalesce((select sum(aberto_centavos) from t where natureza='pagar'),0),
 'receber_atrasado',coalesce((select sum(aberto_centavos) from t where natureza='receber' and vencimento<(now() at time zone 'America/Sao_Paulo')::date),0),
 'pagar_atrasado',coalesce((select sum(aberto_centavos) from t where natureza='pagar' and vencimento<(now() at time zone 'America/Sao_Paulo')::date),0),
 'revisar_custos',(select count(*) from t where automatico and not provisorio and not custos_revisados and competencia between p_inicio and p_fim)) into resumo;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into contas from (select b.conta,sum((case when b.estorno_de is null then 1 else -1 end)*(case when t.natureza='receber' then b.valor_centavos-b.taxa_centavos else -b.valor_centavos end))::bigint saldo from public.baixas_financeiras b join public.titulos_financeiros t on t.id=b.titulo_id where b.oficina_id=p_oficina group by b.conta) x;
 select count(*) into total from private.financeiro_saldos t where t.oficina_id=p_oficina and (p_os is null or t.ordem_servico_id=p_os) and (p_natureza='' or t.natureza=p_natureza) and concat(t.descricao,' ',t.pessoa) ilike '%'||left(p_busca,120)||'%' and
 case p_filtro when 'abertos' then t.cancelado_em is null and t.aberto_centavos>0 when 'atrasados' then t.cancelado_em is null and t.aberto_centavos>0 and t.vencimento<(now() at time zone 'America/Sao_Paulo')::date when 'pagos' then t.cancelado_em is null and t.aberto_centavos=0 and t.competencia between p_inicio and p_fim when 'cancelados' then t.cancelado_em is not null and t.competencia between p_inicio and p_fim when 'vencimentos' then t.cancelado_em is null and t.vencimento between p_inicio and p_fim else t.cancelado_em is null and t.competencia between p_inicio and p_fim end;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into lista from (select t.* from private.financeiro_saldos t where t.oficina_id=p_oficina and (p_os is null or t.ordem_servico_id=p_os) and (p_natureza='' or t.natureza=p_natureza) and concat(t.descricao,' ',t.pessoa) ilike '%'||left(p_busca,120)||'%' and
 case p_filtro when 'abertos' then t.cancelado_em is null and t.aberto_centavos>0 when 'atrasados' then t.cancelado_em is null and t.aberto_centavos>0 and t.vencimento<(now() at time zone 'America/Sao_Paulo')::date when 'pagos' then t.cancelado_em is null and t.aberto_centavos=0 and t.competencia between p_inicio and p_fim when 'cancelados' then t.cancelado_em is not null and t.competencia between p_inicio and p_fim when 'vencimentos' then t.cancelado_em is null and t.vencimento between p_inicio and p_fim else t.cancelado_em is null and t.competencia between p_inicio and p_fim end order by t.vencimento,t.id limit 30 offset greatest(p_pagina,0)*30) x;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into os from (
 select t.id,t.ordem_servico_id,t.descricao,t.pessoa,t.valor_centavos,t.custos_revisados,
 coalesce((select sum(round(-m.quantidade*m.custo_centavos)) from public.movimentacoes_estoque m where m.oficina_id=p_oficina and m.ordem_servico_id=t.ordem_servico_id),0)::bigint as pecas,
 coalesce((select sum(d.valor_centavos) from public.titulos_financeiros d where d.oficina_id=p_oficina and d.ordem_servico_id=t.ordem_servico_id and d.natureza='pagar' and d.cancelado_em is null and d.categoria not in ('compra_estoque','retirada','saldo_inicial','transferencia')),0)::bigint despesas,
 coalesce((select sum(case when b.estorno_de is null then b.taxa_centavos else -b.taxa_centavos end) from public.baixas_financeiras b where b.titulo_id=t.id),0)::bigint taxas
 from public.titulos_financeiros t where t.oficina_id=p_oficina and t.automatico and not t.provisorio and t.cancelado_em is null and t.competencia between p_inicio and p_fim order by t.competencia desc,t.id limit 100) x;
 return jsonb_build_object('resumo',resumo,'contas',contas,'itens',lista,'total',total,'ordens',os);end $$;
create or replace function public.salvar_titulo_financeiro(p_oficina uuid,p_id uuid,p_dados jsonb,p_revisao integer default null) returns uuid language plpgsql security definer set search_path='' as $$
declare t public.titulos_financeiros%rowtype;u uuid;v bigint;n text;c text;begin
 u:=private.exigir_financeiro(p_oficina);if p_id is null then raise exception 'Identificador obrigatório' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_oficina::text||p_id::text,0));
 select * into t from public.titulos_financeiros where oficina_id=p_oficina and id=p_id for update;
 if found and p_revisao is null then return p_id;end if;
 if t.id is not null and (t.revisao is distinct from p_revisao or t.cancelado_em is not null) then raise exception 'Lançamento alterado ou cancelado. Atualize a tela.' using errcode='40001';end if;
 v:=(p_dados->>'valor_centavos')::bigint;n:=p_dados->>'natureza';c:=p_dados->>'categoria';
 if v is null or v not between 1 and 10000000000 or n is null or n not in ('pagar','receber') or c is null or
 (n='receber' and c not in ('servicos','outras_receitas','aporte','saldo_inicial')) or
 (n='pagar' and c not in ('pecas_externas','pessoal','aluguel','agua_luz','impostos','terceiros','outras_despesas','compra_estoque','retirada','saldo_inicial')) or
 length(trim(coalesce(p_dados->>'descricao',''))) not between 3 and 200 or (p_dados->>'competencia')::date is null or (p_dados->>'vencimento')::date is null then raise exception 'Confira descrição, categoria, datas e valor.' using errcode='22023';end if;
 if t.id is not null and (t.automatico or t.compra_id is not null or exists(select 1 from public.baixas_financeiras where titulo_id=t.id)) then
 if v<>t.valor_centavos or n<>t.natureza or c<>t.categoria or (p_dados->>'competencia')::date<>t.competencia or nullif(p_dados->>'ordem_servico_id','')::uuid is distinct from t.ordem_servico_id then raise exception 'Após pagamento ou integração com OS, apenas descrição, vencimento e observações podem mudar. Estorne e cancele para corrigir valores manuais.' using errcode='22023';end if;end if;
 if nullif(p_dados->>'ordem_servico_id','') is not null and not exists(select 1 from public.ordens_servico where oficina_id=p_oficina and id=(p_dados->>'ordem_servico_id')::uuid) then raise exception 'OS não encontrada nesta oficina' using errcode='22023';end if;
 if n='receber' and nullif(p_dados->>'ordem_servico_id','') is not null and t.id is null then raise exception 'A receita da OS é gerada automaticamente na entrega.' using errcode='22023';end if;
 insert into public.titulos_financeiros(id,oficina_id,natureza,descricao,categoria,valor_centavos,competencia,vencimento,pessoa,observacoes,ordem_servico_id,criado_por)
 values(p_id,p_oficina,n,trim(p_dados->>'descricao'),c,v,(p_dados->>'competencia')::date,(p_dados->>'vencimento')::date,coalesce(p_dados->>'pessoa',''),coalesce(p_dados->>'observacoes',''),nullif(p_dados->>'ordem_servico_id','')::uuid,u)
 on conflict(id) do update set descricao=excluded.descricao,natureza=excluded.natureza,categoria=excluded.categoria,valor_centavos=excluded.valor_centavos,competencia=excluded.competencia,vencimento=excluded.vencimento,pessoa=excluded.pessoa,observacoes=excluded.observacoes,ordem_servico_id=excluded.ordem_servico_id,revisao=public.titulos_financeiros.revisao+1 where titulos_financeiros.oficina_id=p_oficina;
 perform private.evento_financeiro(p_oficina,p_id,'saved');return p_id;end $$;
create or replace function public.cancelar_titulo_financeiro(p_oficina uuid,p_titulo uuid,p_revisao integer,p_motivo text) returns void language plpgsql security definer set search_path='' as $$
declare t public.titulos_financeiros%rowtype;begin
 perform private.exigir_financeiro(p_oficina);select * into t from public.titulos_financeiros where oficina_id=p_oficina and id=p_titulo for update;
 if not found then raise exception 'Lançamento não encontrado' using errcode='P0002';end if;
 if t.revisao is distinct from p_revisao then raise exception 'Atualize o lançamento antes de cancelar.' using errcode='40001';end if;
 if t.automatico or t.compra_id is not null or (select baixado_centavos from private.financeiro_saldos where id=t.id)<>0 or length(trim(coalesce(p_motivo,''))) not between 3 and 1000 then raise exception 'Estorne os pagamentos e informe o motivo. Receitas de OS e compras integradas não podem ser canceladas por aqui.' using errcode='22023';end if;
 update public.titulos_financeiros set cancelado_em=now(),motivo_cancelamento=p_motivo,revisao=revisao+1 where id=t.id;
 perform private.evento_financeiro(p_oficina,t.id,'cancelled');end $$;
create or replace function public.estornar_movimentacao_estoque(p_oficina uuid,p_movimento uuid,p_motivo text) returns uuid language plpgsql security definer set search_path='' as $$
declare m public.movimentacoes_estoque%rowtype;e public.estoque_produtos%rowtype;u uuid;novo uuid;begin
 u:=private.exigir_estoque(p_oficina);if not exists(select 1 from public.membros_oficina where oficina_id=p_oficina and usuario_id=u and ativo and perfil in ('owner','manager')) then raise exception 'Somente a gerência pode estornar.' using errcode='42501';end if;
 select * into m from public.movimentacoes_estoque where oficina_id=p_oficina and id=p_movimento;if not found then raise exception 'Movimentação não encontrada' using errcode='P0002';end if;
 select * into e from public.estoque_produtos where oficina_id=p_oficina and item_catalogo_id=m.item_catalogo_id for update;
 select id into novo from public.movimentacoes_estoque where estorno_de=m.id;if found then return novo;end if;
 if m.compra_id is not null then raise exception 'Cancele a compra na tela de compras para reverter estoque e financeiro juntos.' using errcode='22023';end if;
 if m.tipo='estorno' or p_motivo is null or length(trim(p_motivo)) not between 3 and 1000 then raise exception 'Informe o motivo. Estornos não podem ser estornados.' using errcode='22023';end if;
 if e.saldo-m.quantidade<0 then raise exception 'O estorno deixaria o estoque negativo.' using errcode='22023';end if;
 update public.estoque_produtos set saldo=saldo-m.quantidade,revisao=revisao+1 where oficina_id=p_oficina and item_catalogo_id=m.item_catalogo_id;
 insert into public.movimentacoes_estoque(oficina_id,item_catalogo_id,tipo,quantidade,saldo_apos,custo_centavos,motivo,ordem_servico_id,item_os_id,estorno_de,chave,criado_por) values(p_oficina,m.item_catalogo_id,'estorno',-m.quantidade,e.saldo-m.quantidade,m.custo_centavos,trim(p_motivo),m.ordem_servico_id,m.item_os_id,m.id,gen_random_uuid(),u) returning id into novo;
 if m.ordem_servico_id is not null then insert into public.historico_ordem_servico(oficina_id,ordem_servico_id,tipo_evento,usuario_autor_id,descricao,metadados) values(p_oficina,m.ordem_servico_id,'stock_returned',u,'Baixa de estoque estornada: '||trim(p_motivo),jsonb_build_object('movimento',novo));end if;
 insert into public.eventos_negocio(oficina_id,tipo_evento,tipo_agregado,agregado_id,versao_agregado,chave_deduplicacao,dados) values(p_oficina,'inventory.reversed','inventory',m.item_catalogo_id,e.revisao+1,'estoque:'||novo,jsonb_build_object('movimento',novo));return novo;end $$;
do $$declare r record;begin for r in select p.oid::regprocedure assinatura from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('listar_fornecedores','salvar_fornecedor','arquivar_fornecedor','registrar_compra_estoque','listar_compras_estoque','consultar_compra_estoque','cancelar_compra_estoque','preparar_financeiro_os','consultar_financeiro_os','combinar_pagamento_os') loop execute format('revoke all on function %s from public,anon',r.assinatura);execute format('grant execute on function %s to authenticated',r.assinatura);end loop;end $$;
notify pgrst,'reload schema';
commit;
